void store_and_convert_panel_cuda(
    torch::Tensor panel, torch::Tensor converted, torch::Tensor source
) {
    TORCH_CHECK(
        panel.is_cuda() && converted.is_cuda() && source.is_cuda(),
        "CUDA tensors required"
    );
    TORCH_CHECK(
        panel.scalar_type() == torch::kFloat32
        && source.scalar_type() == torch::kFloat32
        && converted.scalar_type() == torch::kFloat16,
        "expected FP32 panel/source and FP16 converted output"
    );
    TORCH_CHECK(
        panel.sizes() == source.sizes()
        && converted.sizes() == source.sizes()
        && source.dim() == 3,
        "panel conversion shapes must match"
    );
    const long long count = source.numel();
    const int threads = 256;
    const int rows = static_cast<int>(source.size(1));
    const int cols = static_cast<int>(source.size(2));
    const bool packed_layout =
        cols % 2 == 0
        && panel.stride(2) == 1
        && converted.stride(2) == 1
        && source.stride(2) == 1
        && panel.stride(0) % 2 == 0
        && panel.stride(1) % 2 == 0
        && converted.stride(0) % 2 == 0
        && converted.stride(1) % 2 == 0
        && source.stride(0) % 2 == 0
        && source.stride(1) % 2 == 0;
    const bool use_float4 =
        packed_layout
        && cols % 4 == 0
        && panel.stride(0) % 4 == 0
        && panel.stride(1) % 4 == 0
        && converted.stride(0) % 4 == 0
        && converted.stride(1) % 4 == 0
        && source.stride(0) % 4 == 0
        && source.stride(1) % 4 == 0;
    if (use_float4) {
        const long long group_count = count / 4;
        const int blocks = static_cast<int>(
            (group_count + threads - 1) / threads
        );
        if (panel.data_ptr<float>() == source.data_ptr<float>()) {
            const int persistent_blocks = blocks < 4096 ? blocks : 4096;
            convert_panel_float4_kernel<<<persistent_blocks, threads>>>(
                reinterpret_cast<__half*>(converted.data_ptr<at::Half>()),
                source.data_ptr<float>(),
                group_count,
                rows,
                cols / 4,
                converted.stride(0), converted.stride(1),
                source.stride(0), source.stride(1)
            );
        } else {
            store_and_convert_panel_float4_kernel<<<blocks, threads>>>(
                panel.data_ptr<float>(),
                reinterpret_cast<__half*>(converted.data_ptr<at::Half>()),
                source.data_ptr<float>(),
                group_count,
                rows,
                cols / 4,
                panel.stride(0), panel.stride(1),
                converted.stride(0), converted.stride(1),
                source.stride(0), source.stride(1)
            );
        }
    } else if (packed_layout) {
        const long long pair_count = count / 2;
        const int blocks = static_cast<int>(
            (pair_count + threads - 1) / threads
        );
        store_and_convert_panel_half2_kernel<<<blocks, threads>>>(
            panel.data_ptr<float>(),
            reinterpret_cast<__half*>(converted.data_ptr<at::Half>()),
            source.data_ptr<float>(),
            pair_count,
            rows,
            cols / 2,
            panel.stride(0), panel.stride(1),
            converted.stride(0), converted.stride(1),
            source.stride(0), source.stride(1)
        );
    } else {
        const int blocks = static_cast<int>((count + threads - 1) / threads);
        store_and_convert_panel_kernel<<<blocks, threads>>>(
            panel.data_ptr<float>(),
            reinterpret_cast<__half*>(converted.data_ptr<at::Half>()),
            source.data_ptr<float>(),
            count,
            rows,
            cols,
            panel.stride(0), panel.stride(1), panel.stride(2),
            converted.stride(0), converted.stride(1), converted.stride(2),
            source.stride(0), source.stride(1), source.stride(2)
        );
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

